// C preprocessor #define parser:
// "#define NAME value" and "#define NAME(params) value"
// Backslash at end continues to next line (joined with space).
// // comments and blank lines ignored. #undef removes a macro.

struct MacroDef {
    std::vector<std::string> params; // empty = object-like
    std::string body;
};

std::string strip_str(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r");
    if (a == std::string::npos) return "";
    return s.substr(a, s.find_last_not_of(" \t\r") - a + 1);
}

std::vector<std::string> split_params(const std::string& s) {
    std::vector<std::string> r; std::istringstream ss(s); std::string p;
    while (std::getline(ss, p, ',')) r.push_back(strip_str(p));
    return r;
}

// Parse a single #define line (after "#define " prefix removed).
// Returns {name, MacroDef} pair.
std::pair<std::string, MacroDef> parse_one_define(const std::string& rest) {
    MacroDef md; std::string name; size_t bs;
    size_t pa = rest.find('('), sp = rest.find(' ');
    if (pa != std::string::npos && (sp == std::string::npos || pa < sp)) {
        name = rest.substr(0, pa); size_t cp = rest.find(')', pa);
        md.params = split_params(rest.substr(pa+1, cp-pa-1)); bs = cp+1;
    } else {
        size_t s = rest.find_first_of(" \t");
        name = (s==std::string::npos) ? rest : rest.substr(0,s);
        bs = (s==std::string::npos) ? rest.size() : s;
    }
    md.body = strip_str(rest.substr(bs));
    return {name, md};
}

